import{_ as t,o as d,c as o,ag as r}from"./chunks/framework.BZohXCq9.js";const m=JSON.parse('{"title":"Admin Dashboard -> Instructor Management (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/admin-dashboard/instructor-management.md","filePath":"modules/admin-dashboard/instructor-management.md"}'),a={name:"modules/admin-dashboard/instructor-management.md"};function n(i,e,l,s,c,u){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="admin-dashboard-instructor-management-deep" tabindex="-1">Admin Dashboard -&gt; Instructor Management (deep) <a class="header-anchor" href="#admin-dashboard-instructor-management-deep" aria-label="Permalink to &quot;Admin Dashboard -&gt; Instructor Management (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>admin-dashboard</code><br><strong>Feature:</strong> <code>instructor-management</code><br><strong>Route:</strong> <code>/admin-dashboard/InstructorManagement</code></p><p>This module lets admins view instructor cards, filter them, inspect full details, and bulk-delete selected instructors.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Show all instructors with enriched admin-facing metrics.</li><li>Filter by gender, verification, experience, and created-at date range.</li><li>Open a detail modal for one instructor.</li><li>Toggle delete mode and bulk-delete selected instructors.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/admin-dashboard/InstructorManagement.tsx</code></td><td>Main route page</td><td>Calls <code>GET_ALL_INSTRUCTORS_DETAILS</code> and <code>DELETE_INSTRUCTORS</code>; owns filter state, selection state, detail modal state, and delete confirmation flow.</td></tr><tr><td><code>Frontend/src/components/AdminComponents/FilterPopOver.tsx</code></td><td>Filter UI</td><td>Collects filter input and passes it back to the page.</td></tr><tr><td><code>Frontend/src/components/AdminComponents/InstructorCard.tsx</code></td><td>Instructor list card</td><td>Displays instructor summary and selection controls.</td></tr><tr><td><code>Frontend/src/components/AdminComponents/InstructorDetailModal.tsx</code></td><td>Detail modal</td><td>Shows expanded instructor information to the admin.</td></tr><tr><td><code>Frontend/src/components/AdminComponents/DeleteConfirmation.tsx</code></td><td>Delete confirmation dialog</td><td>Used before bulk-delete.</td></tr><tr><td><code>Frontend/src/graphql/Queries/InstructorProfiles.ts</code></td><td>GraphQL operations</td><td>Defines <code>GET_ALL_INSTRUCTORS_DETAILS</code> and <code>DELETE_INSTRUCTORS</code>.</td></tr><tr><td><code>Frontend/src/types/Instructor.ts</code></td><td>TS interfaces</td><td>Defines instructor payload and filter types used by the page.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="get-all-instructors-details" tabindex="-1"><code>GET_ALL_INSTRUCTORS_DETAILS</code> <a class="header-anchor" href="#get-all-instructors-details" aria-label="Permalink to &quot;`GET_ALL_INSTRUCTORS_DETAILS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/InstructorProfiles.ts</code></li><li>Query field: <code>allInstructorsWithDetails</code></li><li>Returns: <ul><li>profile fields</li><li>verification fields</li><li>documents</li><li>derived fields such as <code>lessonPrice</code>, <code>studentCount</code>, <code>reviewRating</code>, <code>reviewsCount</code></li></ul></li><li>Used by: <code>InstructorManagement.tsx</code></li></ul><h3 id="delete-instructors" tabindex="-1"><code>DELETE_INSTRUCTORS</code> <a class="header-anchor" href="#delete-instructors" aria-label="Permalink to &quot;`DELETE_INSTRUCTORS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/InstructorProfiles.ts</code></li><li>Mutation field: <code>deleteInstructors(instructorIds: [ID!]!)</code></li><li>Used by: <code>InstructorManagement.tsx</code></li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs.js</code></li><li>Relevant query field: <ul><li><code>allInstructorsWithDetails: [InstructorWithDetails!]</code></li></ul></li><li>Relevant mutation field: <ul><li><code>deleteInstructors(instructorIds: [ID!]!): DeleteInstructorsResponse!</code></li></ul></li><li>Relevant types: <ul><li><code>InstructorWithDetails</code></li><li><code>DeleteInstructorsResponse</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers.js</code></li><li>Relevant query resolver: <ul><li><code>allInstructorsWithDetails</code><ul><li>Admin-only</li><li>Reads all instructors</li><li>Enriches each instructor with: <ul><li>tariff data from <code>TeacherTariff</code></li><li>booking-derived student count from <code>studentBookingModel</code></li><li>review average and review count from <code>Review</code></li></ul></li></ul></li></ul></li><li>Relevant mutation resolver: <ul><li><code>deleteInstructors</code><ul><li>Admin-only</li><li>Deletes instructors with <code>Instructor.deleteMany({ _id: { $in: instructorIds } })</code></li><li>Returns <code>{ success, message }</code></li></ul></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/User</code></td><td>Source of <code>Instructor</code> documents</td></tr><tr><td><code>server/src/models/teacherTariff.model.js</code></td><td>Used to derive <code>lessonPrice</code></td></tr><tr><td><code>server/src/models/studentBooking.model.js</code></td><td>Used to derive <code>studentCount</code></td></tr><tr><td><code>server/src/models/Reviews.js</code></td><td>Used to derive <code>reviewRating</code> and <code>reviewsCount</code></td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Admin opens <code>InstructorManagement.tsx</code>.</li><li><code>GET_ALL_INSTRUCTORS_DETAILS</code> loads enriched instructor records.</li><li>Frontend applies filters with <code>useMemo</code>; filtering is client-side after fetch.</li><li>Admin can open <code>InstructorDetailModal</code> for one instructor.</li><li>In delete mode, selected ids are stored locally.</li><li>Confirm delete -&gt; <code>DELETE_INSTRUCTORS</code>.</li><li>Backend deletes matching instructors and frontend refetches the list.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>Filters are handled in the frontend, not passed to GraphQL.</li><li>The enriched query is intentionally heavier than <code>allInstructors</code>; it is the admin-facing query for management screens.</li><li>The page uses <code>notifyOnNetworkStatusChange</code> so refetch states can be surfaced cleanly.</li></ul>',23)])])}const f=t(a,[["render",n]]);export{m as __pageData,f as default};
